import { ChangeEvent, useEffect, useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { Copy, Eye, EyeOff, ImagePlus, Pencil, Plus, Trash2 } from 'lucide-react';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/contexts/AuthContext';
import { toast } from 'sonner';

type Draft={id?:string;name:string;price:string;duration:string;description:string;highlights:string;album_included:boolean;album_details:string;travel_included:boolean;travel_details:string;addons:{name:string;price:string}[];files:File[]};
const empty=():Draft=>({name:'',price:'',duration:'',description:'',highlights:'',album_included:false,album_details:'',travel_included:false,travel_details:'',addons:[],files:[]});
export default function PhotographerPackageManager({provider}:{provider:any}) { const {user}=useAuth(); const qc=useQueryClient(); const [draft,setDraft]=useState<Draft|null>(null); const [busy,setBusy]=useState(false); const [availability,setAvailability]=useState({date:'',available:true,note:''});
 const {data:packages=[],isLoading}=useQuery({queryKey:['photography-packages',provider.id],queryFn:async()=>{const {data,error}=await supabase.from('photography_packages' as any).select('*, photography_package_images(*), photography_package_highlights(*), photography_package_addons(*)').eq('photographer_id',provider.id).order('created_at',{ascending:false});if(error)throw error;return data??[]}});
 const {data:bookings=[]}=useQuery({queryKey:['photography-bookings',provider.id],queryFn:async()=>{const {data,error}=await supabase.from('photography_package_bookings' as any).select('id,total_amount,status').eq('photographer_id',provider.id);if(error)throw error;return data??[]}});
 const refresh=()=>qc.invalidateQueries({queryKey:['photography-packages',provider.id]});
 useEffect(()=>{const ch=supabase.channel(`photographer-packages-${provider.id}`).on('postgres_changes',{event:'*',schema:'public',table:'photography_packages',filter:`photographer_id=eq.${provider.id}`},refresh).on('postgres_changes',{event:'*',schema:'public',table:'photography_package_bookings',filter:`photographer_id=eq.${provider.id}`},()=>qc.invalidateQueries({queryKey:['photography-bookings',provider.id]})).subscribe();return()=>{supabase.removeChannel(ch)}},[provider.id]);
 const edit=(p:any)=>setDraft({id:p.id,name:p.name,price:String(p.price),duration:p.duration??'',description:p.description??'',highlights:(p.photography_package_highlights??[]).map((x:any)=>x.text).join('\n'),album_included:p.album_included,album_details:p.album_details??'',travel_included:p.travel_included,travel_details:p.travel_details??'',addons:(p.photography_package_addons??[]).map((x:any)=>({name:x.name,price:String(x.price)})),files:[]});
 const upload=async(id:string,files:File[])=>{if(!user)return;for(const [i,file] of files.entries()){if(!file.type.startsWith('image/')||file.size>8*1024*1024)throw new Error('Use image files under 8MB');const path=`${user.id}/${id}/${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const {error}=await supabase.storage.from('photography-package-images').upload(path,file,{contentType:file.type});if(error)throw error;const {data}=supabase.storage.from('photography-package-images').getPublicUrl(path);const r=await supabase.from('photography_package_images' as any).insert({package_id:id,storage_path:path,public_url:data.publicUrl,alt_text:file.name,is_cover:i===0,sort_order:i});if(r.error)throw r.error;}};
 const save=async()=>{if(!draft||!draft.name.trim()||Number(draft.price)<0||draft.price===''){toast.error('Enter package name and valid price');return}setBusy(true);try{const payload={photographer_id:provider.id,name:draft.name.trim(),price:Number(draft.price),duration:draft.duration||null,description:draft.description||null,album_included:draft.album_included,album_details:draft.album_details||null,travel_included:draft.travel_included,travel_details:draft.travel_details||null};const r=draft.id?await supabase.from('photography_packages' as any).update(payload).eq('id',draft.id).select().single():await supabase.from('photography_packages' as any).insert(payload).select().single();if(r.error)throw r.error;const id=r.data.id;if(draft.id){await supabase.from('photography_package_highlights' as any).delete().eq('package_id',id);await supabase.from('photography_package_addons' as any).delete().eq('package_id',id)}const highs=draft.highlights.split('\n').map(text=>text.trim()).filter(Boolean).map((text,sort_order)=>({package_id:id,text,sort_order}));if(highs.length)await supabase.from('photography_package_highlights' as any).insert(highs);const addons=draft.addons.filter(a=>a.name.trim()&&a.price!=='').map((a,sort_order)=>({package_id:id,name:a.name.trim(),price:Number(a.price),sort_order}));if(addons.length)await supabase.from('photography_package_addons' as any).insert(addons);await upload(id,draft.files);toast.success('Photography package saved');setDraft(null);refresh()}catch(e:any){toast.error(e.message||'Could not save package')}finally{setBusy(false)}};
 const action=async(p:any,kind:'delete'|'hide'|'duplicate')=>{if(kind==='delete'&&!confirm('Delete this package?'))return;let r:any;if(kind==='delete')r=await supabase.from('photography_packages' as any).delete().eq('id',p.id);else if(kind==='hide')r=await supabase.from('photography_packages' as any).update({is_visible:!p.is_visible}).eq('id',p.id);else r=await supabase.from('photography_packages' as any).insert({photographer_id:provider.id,name:`${p.name} (Copy)`,price:p.price,duration:p.duration,description:p.description,album_included:p.album_included,album_details:p.album_details,travel_included:p.travel_included,travel_details:p.travel_details,is_visible:false,is_active:false});if(r.error)toast.error(r.error.message);else{toast.success(kind==='duplicate'?'Draft duplicated':'Package updated');refresh()}};
 const saveAvailability=async()=>{if(!availability.date)return;const {error}=await supabase.from('photographer_availability' as any).upsert({photographer_id:provider.id,available_date:availability.date,is_available:availability.available,note:availability.note},{onConflict:'photographer_id,available_date'});if(error)toast.error(error.message);else toast.success('Availability saved')}; const revenue=bookings.filter((b:any)=>b.status!=='cancelled').reduce((n:number,b:any)=>n+Number(b.total_amount),0);
 return <div className="max-w-[1200px] space-y-6"><div className="flex flex-wrap justify-between gap-3"><div><h1 className="text-xl font-bold">Photography Packages</h1><p className="text-sm text-muted-foreground">Photography-only packages, albums, travel and booking availability.</p></div><button onClick={()=>setDraft(empty())} className="rounded-xl bg-[#8B1538] px-4 py-2.5 text-sm font-semibold text-white"><Plus className="mr-1 inline h-4 w-4"/>Create package</button></div><div className="grid grid-cols-2 gap-3 md:grid-cols-4"><Stat label="Packages" value={packages.length}/><Stat label="Bookings" value={bookings.length}/><Stat label="Revenue" value={`₹${revenue.toLocaleString('en-IN')}`}/><Stat label="Live" value={packages.filter((p:any)=>p.is_visible&&p.is_active).length}/></div><div className="rounded-2xl border bg-white p-4 flex flex-wrap gap-3 items-end"><Field label="Availability date"><input type="date" value={availability.date} onChange={e=>setAvailability({...availability,date:e.target.value})}/></Field><label className="text-sm"><input type="checkbox" checked={availability.available} onChange={e=>setAvailability({...availability,available:e.target.checked})}/> Available</label><Field label="Note"><input value={availability.note} onChange={e=>setAvailability({...availability,note:e.target.value})}/></Field><button onClick={saveAvailability} className="rounded-xl border px-4 py-2 text-sm font-semibold">Save availability</button></div>{isLoading?<div className="h-48 animate-pulse rounded-2xl bg-muted"/>:<div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">{packages.map((p:any)=><div key={p.id} className="overflow-hidden rounded-2xl border bg-white"><div className="h-32 bg-secondary">{p.photography_package_images?.[0]&&<img className="h-full w-full object-cover" src={p.photography_package_images[0].public_url}/>}</div><div className="p-4"><div className="flex justify-between"><h2 className="font-bold">{p.name}</h2><span className="text-xs">{p.is_visible?'LIVE':'HIDDEN'}</span></div><p className="mt-1 text-lg font-bold">₹{Number(p.price).toLocaleString('en-IN')}</p><p className="text-xs text-muted-foreground">{p.duration} {p.album_included?' · Album':''} {p.travel_included?' · Travel':''}</p><div className="mt-4 flex gap-2"><button onClick={()=>edit(p)} className="flex-1 rounded-lg border py-2 text-xs"><Pencil className="mr-1 inline h-3"/>Edit</button><button onClick={()=>action(p,'duplicate')} className="rounded-lg border p-2"><Copy className="h-3"/></button><button onClick={()=>action(p,'hide')} className="rounded-lg border p-2">{p.is_visible?<EyeOff className="h-3"/>:<Eye className="h-3"/>}</button><button onClick={()=>action(p,'delete')} className="rounded-lg border border-red-200 p-2 text-red-600"><Trash2 className="h-3"/></button></div></div></div>)}</div>}{draft&&<Editor d={draft} set={setDraft} save={save} close={()=>setDraft(null)} busy={busy}/>}</div> }
function Editor({d,set,save,close,busy}:any){const patch=(x:any)=>set((v:Draft)=>({...v,...x}));return <div className="fixed inset-0 z-[70] overflow-y-auto bg-black/50 p-4"><div className="mx-auto max-w-2xl rounded-2xl bg-white p-6 space-y-4"><h2 className="font-bold">{d.id?'Edit':'Create'} photography package</h2><div className="grid gap-3 sm:grid-cols-2"><Field label="Name"><input value={d.name} onChange={e=>patch({name:e.target.value})}/></Field><Field label="Price"><input type="number" value={d.price} onChange={e=>patch({price:e.target.value})}/></Field><Field label="Duration"><input value={d.duration} onChange={e=>patch({duration:e.target.value})} placeholder="8 hours"/></Field><Field label="Photos"><input type="file" accept="image/*" multiple onChange={(e:ChangeEvent<HTMLInputElement>)=>patch({files:[...d.files,...Array.from(e.target.files??[])]})}/></Field></div><Field label="Description"><textarea value={d.description} onChange={e=>patch({description:e.target.value})}/></Field><Field label="Highlights (one per line)"><textarea value={d.highlights} onChange={e=>patch({highlights:e.target.value})}/></Field><div className="grid gap-3 sm:grid-cols-2"><label className="text-sm"><input type="checkbox" checked={d.album_included} onChange={e=>patch({album_included:e.target.checked})}/> Album included</label><Field label="Album details"><input value={d.album_details} onChange={e=>patch({album_details:e.target.value})}/></Field><label className="text-sm"><input type="checkbox" checked={d.travel_included} onChange={e=>patch({travel_included:e.target.checked})}/> Travel included</label><Field label="Travel details"><input value={d.travel_details} onChange={e=>patch({travel_details:e.target.value})}/></Field></div><Field label="Add-ons"><div className="space-y-2">{d.addons.map((a:any,i:number)=><div key={i} className="flex gap-2"><input placeholder="Add-on" value={a.name} onChange={e=>patch({addons:d.addons.map((x:any,j:number)=>j===i?{...x,name:e.target.value}:x)})}/><input type="number" placeholder="Price" value={a.price} onChange={e=>patch({addons:d.addons.map((x:any,j:number)=>j===i?{...x,price:e.target.value}:x)})}/></div>)}<button onClick={()=>patch({addons:[...d.addons,{name:'',price:''}]})} className="text-xs font-bold text-maroon"><ImagePlus className="mr-1 inline h-3"/>Add add-on</button></div></Field><div className="flex gap-3"><button onClick={close} className="flex-1 rounded-xl border py-2.5">Cancel</button><button disabled={busy} onClick={save} className="flex-1 rounded-xl bg-[#8B1538] py-2.5 text-white">{busy?'Saving…':'Save package'}</button></div></div></div>}; function Field({label,children}:any){return <label className="block text-sm font-medium">{label}<div className="mt-1 [&_input]:w-full [&_input]:rounded-lg [&_input]:border [&_input]:p-2 [&_textarea]:w-full [&_textarea]:rounded-lg [&_textarea]:border [&_textarea]:p-2">{children}</div></label>}; function Stat({label,value}:any){return <div className="rounded-2xl border bg-white p-4"><p className="text-xs text-muted-foreground">{label}</p><p className="text-lg font-bold">{value}</p></div>}
